//! The input of a package (spec §15.1): the files a command reads from the
//! one path it is given, and the [`Loaded`] package they make.
//!
//! [`read_input`] reads the file system; [`Loaded::from_input`] reads no file,
//! so the CLI, the tests and `onsa_web` meet there (R-80 (5), plan D-05). The
//! tree of a package is collected by `onsa_sema::package_tree`, the one place
//! of that rule (std is generated by it too).

use std::ffi::OsStr;
use std::path::{Component, Path, PathBuf};

use onsa_diag::{FileId, SourceMap};
use onsa_sema::package_tree::{self, BUILD_DIR, MANIFEST, SUFFIX};

use crate::Manifest;

/// One source file of a package input: its path (relative to the package
/// root with a manifest; as given without one; `/` between the parts either
/// way, [`slash_path`]) and its text.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SourceFile {
    pub path: String,
    pub text: String,
}

/// The manifest of an input as its text, so that the manifest's check can
/// point into it (W4-02).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ManifestSource {
    /// The file string of the manifest in diagnostics: `onsa.toml` for the
    /// manifest of a package root (relative to the root, S-234); a test
    /// fragment gives its case file, whose lines the text keeps.
    pub path: String,
    pub text: String,
}

/// What a build reads, without the file system (R-80 (5), plan D-05): the
/// manifest's text and the list of sources. [`read_input`] makes one from
/// files; the tests and `onsa_web` make one from their own data.
#[derive(Debug, Clone, Default)]
pub struct PackageInput {
    /// `None`: no `onsa.toml`; the one file is a one-module package named
    /// after its stem (spec §15.1).
    pub manifest: Option<ManifestSource>,
    pub files: Vec<SourceFile>,
    /// The package root on disk, when there is one (the default output directory of `build`).
    pub root: Option<PathBuf>,
    /// The file passed inside a package (§15.1), by its path in `files`: the
    /// commands narrow their results to its module.
    pub focus: Option<String>,
}

impl PackageInput {
    /// A single file without a manifest: a one-module package.
    pub fn single_file(path: impl Into<String>, text: impl Into<String>) -> PackageInput {
        PackageInput { files: vec![SourceFile { path: path.into(), text: text.into() }], ..PackageInput::default() }
    }
}

/// Files of one package, loaded into a `SourceMap` with their module paths.
#[derive(Debug)]
pub struct Loaded {
    pub sources: SourceMap,
    pub name: String,
    pub root: Option<PathBuf>,
    pub modules: Vec<(FileId, String)>,
    /// The manifest; `None` for a single file without `onsa.toml` (spec §15.1).
    pub manifest: Option<Manifest>,
    /// The file passed inside a package ([`PackageInput::focus`]).
    pub focus: Option<FileId>,
}

/// Load the package of `path` (spec §15.1; `None` is the working directory).
pub fn load(path: Option<&Path>) -> Result<Loaded, String> {
    Loaded::from_input(read_input(path)?)
}

impl Loaded {
    /// The sources of `input` in a `SourceMap` with their module paths, and
    /// its manifest read. Reads no file.
    pub fn from_input(input: PackageInput) -> Result<Loaded, String> {
        let manifest = match &input.manifest {
            Some(m) => Some(parse_manifest(m, input.root.as_deref())?),
            None => None,
        };
        let name = match (&manifest, input.files.as_slice()) {
            (Some(m), _) => m.package.name.clone(),
            (None, [file]) => stem(&file.path),
            (None, files) => return Err(format!("an input without onsa.toml is one file, not {}", files.len())),
        };
        let mut sources = SourceMap::default();
        let mut modules = Vec::with_capacity(input.files.len());
        let mut focus = None;
        for f in input.files {
            let module = if manifest.is_some() { module_path(Path::new(&f.path)) } else { stem(&f.path) };
            let is_focus = input.focus.as_deref() == Some(f.path.as_str());
            let file = sources.add(f.path, f.text);
            if is_focus {
                focus = Some(file);
            }
            modules.push((file, module));
        }
        if let Some(f) = &input.focus
            && focus.is_none()
        {
            return Err(format!("{f}: the file to narrow to is not a file of the input"));
        }
        Ok(Loaded { sources, name, root: input.root, modules, manifest, focus })
    }
}

/// Read the manifest of `source`. The errors name the manifest by its place
/// under `root` when there is one (the CLI), else by its file string.
pub(crate) fn parse_manifest(source: &ManifestSource, root: Option<&Path>) -> Result<Manifest, String> {
    let shown = root.map_or_else(|| source.path.clone(), |r| r.join(MANIFEST).display().to_string());
    Manifest::parse(&source.text, &[]).map(|(m, _)| m).map_err(|e| format!("{shown}: {e}"))
}

fn stem(path: &str) -> String {
    Path::new(path).file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default()
}

/// The input of the package of `path` (spec §15.1): one path, a `.onsa`
/// file, a package directory or an `onsa.toml`; `None` is the working
/// directory, searched upward like a file.
///
/// - A directory is a package root: it has an `onsa.toml`, and nothing is
///   searched above it.
/// - An `onsa.toml` is the directory where it is (S-622): a link is followed
///   only to read it.
/// - A `.onsa` file is searched upward from its real place (the links of the
///   path resolved, S-592 (4)). Found, the whole package is read and the file
///   is the focus; it may not be under the root's `target/`. Not found, it is
///   a one-module package named and shown as it was passed (S-234).
///
/// Every item is looked at before it is opened, so a FIFO does not block.
pub fn read_input(path: Option<&Path>) -> Result<PackageInput, String> {
    let Some(path) = path else {
        let cwd = std::env::current_dir()
            .and_then(|d| d.canonicalize())
            .map_err(|e| format!("cannot read the working directory: {e}"))?;
        let root = find_root(&cwd)?.ok_or("no onsa.toml in the working directory or above it")?;
        return read_package(&root, None);
    };
    let meta = std::fs::metadata(path).map_err(|e| format!("cannot read {}: {e}", path.display()))?;
    // SPEC-GAP(S-637): the kind of a passed file is that of the name as it
    // was passed, not of the place a link points at: `cut -> b.onsa` is
    // neither a `.onsa` file nor `onsa.toml` (exit 2).
    // The name `onsa.toml` comes first: what it names is read as the
    // manifest, so a link to a directory is not that directory (exit 2).
    let name = path.file_name().unwrap_or_default();
    if name == OsStr::new(MANIFEST) {
        return read_package(manifest_dir(path), None);
    }
    if meta.is_dir() {
        if !package_tree::has_manifest(path)? {
            return Err(format!("{} has no onsa.toml", path.display()));
        }
        return read_package(path, None);
    }
    if !name.as_encoded_bytes().ends_with(SUFFIX.as_bytes()) {
        return Err(format!("{}: not a `.onsa` file or onsa.toml", path.display()));
    }
    // SPEC-GAP(S-635): a passed `.onsa` that is not a regular file (a FIFO,
    // a link to one) is looked at before it is opened and is a usage error (2).
    if !meta.is_file() {
        return Err(format!("{}: not a regular file", path.display()));
    }
    let real = path.canonicalize().map_err(|e| format!("cannot read {}: {e}", path.display()))?;
    let Some(root) = find_root(real.parent().expect("a file is in a directory"))? else {
        return Ok(PackageInput::single_file(slash_path(path), read_text(path)?));
    };
    let rel = real.strip_prefix(&root).expect("the root is above the file");
    let mut parts = rel.components();
    if parts.next() == Some(Component::Normal(OsStr::new(BUILD_DIR))) && parts.next().is_some() {
        return Err(format!(
            "{}: a file under the `target/` of the package root {} is a build output, not a module",
            path.display(),
            root.display()
        ));
    }
    read_package(&root, Some(rel))
}

/// The directory of the manifest at `manifest` (`.` for a bare `onsa.toml`, R-178).
pub fn manifest_dir(manifest: &Path) -> &Path {
    manifest.parent().filter(|p| !p.as_os_str().is_empty()).unwrap_or(Path::new("."))
}

/// The first directory from `start` upward that has an `onsa.toml`.
fn find_root(start: &Path) -> Result<Option<PathBuf>, String> {
    for dir in start.ancestors() {
        if package_tree::has_manifest(dir)? {
            return Ok(Some(dir.to_path_buf()));
        }
    }
    Ok(None)
}

/// The package at `root`: its manifest and its files. `focus` (relative to
/// `root`) is a file passed inside it; when the tree leaves it out by its
/// name (under a `.` name or the root's `tests/`), it is read as a module
/// too, for the diagnostics of its name (W4-14 U2).
fn read_package(root: &Path, focus: Option<&Path>) -> Result<PackageInput, String> {
    let manifest = read_manifest(root)?;
    let mut rels = package_tree::onsa_files(root)?;
    let focus = match focus {
        Some(f) => {
            if !rels.iter().any(|r| r == f) {
                rels.push(f.to_path_buf());
                rels.sort();
            }
            Some(rel_string(f)?)
        }
        None => None,
    };
    let files = read_files(root, &rels)?;
    Ok(PackageInput { manifest: Some(manifest), files, root: Some(root.to_path_buf()), focus })
}

/// The manifest of the package root `dir`. A link is followed; what it
/// names must be a regular file (looked at before it is opened).
pub fn read_manifest(dir: &Path) -> Result<ManifestSource, String> {
    let path = dir.join(MANIFEST);
    let meta = std::fs::metadata(&path).map_err(|e| format!("cannot read {}: {e}", path.display()))?;
    if !meta.is_file() {
        return Err(format!("{}: not a regular file", path.display()));
    }
    Ok(ManifestSource { path: MANIFEST.to_string(), text: read_text(&path)? })
}

/// The `.onsa` files of the package at `root` (spec §15.1,
/// `onsa_sema::package_tree`), sorted part by part, with paths relative to
/// it and `/` between their parts.
pub fn read_sources(root: &Path) -> Result<Vec<SourceFile>, String> {
    read_files(root, &package_tree::onsa_files(root)?)
}

fn read_files(root: &Path, rels: &[PathBuf]) -> Result<Vec<SourceFile>, String> {
    rels.iter().map(|rel| Ok(SourceFile { path: rel_string(rel)?, text: read_text(&root.join(rel))? })).collect()
}

fn read_text(path: &Path) -> Result<String, String> {
    std::fs::read_to_string(path).map_err(|e| format!("cannot read {}: {e}", path.display()))
}

/// A path relative to a root, `/` between its parts.
fn rel_string(rel: &Path) -> Result<String, String> {
    let parts: Option<Vec<&str>> = rel.components().map(|c| c.as_os_str().to_str()).collect();
    parts.map(|p| p.join("/")).ok_or_else(|| format!("{}: the name is not UTF-8", rel.display()))
}

/// Module path of a file relative to the package root: `dsp/voice.onsa` -> `dsp.voice`.
pub fn module_path(rel: &Path) -> String {
    let no_ext = rel.with_extension("");
    no_ext.components().map(|c| c.as_os_str().to_string_lossy().into_owned()).collect::<Vec<_>>().join(".")
}

/// The name of a source file in diagnostics (§18.1, S-234): the path with
/// `/` between its parts. Nothing else changes: `./` and `..` stay as they
/// were passed. Only the `\` of Windows is a separator to turn; elsewhere it is
/// a character of the name.
pub fn slash_path(path: &Path) -> String {
    let text = path.to_string_lossy();
    if std::path::MAIN_SEPARATOR == '/' { text.into_owned() } else { text.replace(std::path::MAIN_SEPARATOR, "/") }
}
